mapper.select:
SELECT t.*, u.username AS author_name, c.name AS category_name, lr.username AS last_reply_by_name FROM forum_topics t LEFT JOIN users u ON t.user_id = u.id LEFT JOIN forum_categories c ON t.category_id = c.id LEFT JOIN users lr ON t.last_reply_by = lr.id WHERE t.status = 1
AND t.category_id = #{categoryId}
ORDER BY t.reply_count DESC, t.created_at DESC
ORDER BY t.view_count DESC, t.created_at DESC
ORDER BY t.created_at DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE forum_topics
SET title = #{title}, content = #{content}, category_id = #{categoryId},
    updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE forum_topics
SET reply_count = reply_count + 1, last_reply_at = #{lastReplyAt}, last_reply_by = #{lastReplyBy}
WHERE id = #{id}
